    private const int Welcome5Cents = 500;
    private const int Summer10CapCents = 1_500;

    public static int Discount(string? code, int remainingCents) =>
        code?.ToUpperInvariant() switch
        {
            "WELCOME5" => Welcome5Cents,
            "SUMMER10" => Math.Min(remainingCents / 10, Summer10CapCents),
            _ => 0,
        };
}

namespace CheckoutPricing.Domain;

public static class DiscountPolicy
{
    public static int TotalDiscount(int subtotalCents, LoyaltyTier tier, string? promoCode)
    {
        var loyaltyPart = LoyaltyDiscountPolicy.LoyaltyPart(subtotalCents, tier);
        var promoPart = PromoCodePolicy.Discount(promoCode, subtotalCents - loyaltyPart);
        return Math.Min(loyaltyPart + promoPart, subtotalCents);
    }
}

namespace CheckoutPricing.Domain;

public static class ShippingPolicy
{
    private const int StandardFeeCents = 490;
    private const int ExpressFeeCents = 990;
    private const int FreeStandardFromCents = 5_000;

    public static int Fee(int payableCents, LoyaltyTier tier, bool express) =>
        express ? ExpressFee(tier) : StandardFee(payableCents, tier);

    private static int ExpressFee(LoyaltyTier tier) =>
        tier == LoyaltyTier.Platinum ? 0 : ExpressFeeCents;

    private static int StandardFee(int payableCents, LoyaltyTier tier) =>
        tier >= LoyaltyTier.Gold || payableCents >= FreeStandardFromCents ? 0 : StandardFeeCents;
}

